<template><div class="workflow"><div class="actions"><el-button v-permission="'sales_automation:admin'" type="primary" @click="batchDialog=true">创建公海批次</el-button></div><el-alert v-if="workflowError" type="error" title="操作失败，请检查策略版本、配额或权限后重试。" :closable="false" show-icon/><CustomerHubWorkspace :key="refreshKey" kind="research" @review-task="handleReview"/><el-dialog v-model="batchDialog" title="创建公海批次" width="520"><el-form label-position="top"><el-form-item label="策略版本"><el-input v-model="batch.policy_version"/></el-form-item><el-form-item label="配额 JSON"><el-input v-model="batch.quotasText" type="textarea" :rows="6"/></el-form-item></el-form><template #footer><el-button @click="batchDialog=false">取消</el-button><el-button type="primary" :loading="workflowLoading" @click="submitBatch">创建</el-button></template></el-dialog></div></template>
<script setup>
import { reactive, ref } from 'vue';import { msgError, msgSuccess } from '@/utils/feedback';import CustomerHubWorkspace from './CustomerHubWorkspace.vue';import { useResearchWorkflows } from './composables/useCustomerHub'
const {workflowLoading,workflowError,createBatch,reviewTask}=useResearchWorkflows();const refreshKey=ref(0),batchDialog=ref(false);const batch=reactive({policy_version:'',quotasText:'{}'})
async function submitBatch(){let quotas;try{quotas=JSON.parse(batch.quotasText)}catch{msgError('配额 JSON 格式错误');return}if(await createBatch({policy_version:batch.policy_version,quotas_json:quotas,profile_conditions:{}})){batchDialog.value=false;refreshKey.value++;msgSuccess('创建公海批次')}}
async function handleReview(row,status){if(await reviewTask(row.research_task_id,status)){refreshKey.value++;msgSuccess(status==='accepted'?'通过复核':'要求修订')}}
</script><style scoped>.workflow{display:grid;gap:12px}.actions{display:flex;justify-content:flex-end}</style>
